const cached = $json.ov_cached;
try {
  const parsed = typeof cached === 'string' ? JSON.parse(cached) : cached;
  return [{ json: { ...parsed, _from_cache: true } }];
} catch (e) {
  return [{ json: { ok: false, _from_cache: false, _parse_error: e.message } }];
}

// Lectura defensiva: soporta nodo Airtable que devuelve {fields:{...}} o campos aplanados.
function F(rec){ return (rec && rec.fields && typeof rec.fields==='object') ? rec.fields : (rec||{}); }
function norm(s){return String(s==null?'':s).toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\bBAJAJ\b/g,' ').replace(/[^A-Z0-9]+/g,' ').trim();}
function toks(s){return norm(s).split(' ').filter(Boolean);}
var CC_LIST=[100,110,125,150,160,180,200,220,250,400];
function extractCC(s){
  var t=norm(s);
  var nums=(t.match(/\d{3}/g)||[]).map(Number);
  for(var i=0;i<nums.length;i++){ if(CC_LIST.indexOf(nums[i])>=0) return nums[i]; }
  var z=t.match(/(\d{3})Z/); if(z && CC_LIST.indexOf(Number(z[1]))>=0) return Number(z[1]);
  return null;
}
function extractVariant(s){
  var t=' '+norm(s)+' ';
  if(/\bNS\d{2,3}\b/.test(t) || /\bNS\b/.test(t)) return 'NS';
  if(/\bN\d{2,3}\b/.test(t) || /\bN\b/.test(t))  return 'N';
  if(/\bF\d{2,3}\b/.test(t) || /\bF\b/.test(t))  return 'F';
  return '';
}
function familyOf(s){ var tk=toks(s); return tk.length?tk[0]:''; }
// Ya NO exigimos .fields en el filtro (eso tiraba todo si el nodo devuelve plano). Solo exigimos id.
const models = $('Airtable · Get Active Models').all().map(i=>i.json).filter(m=>m && m.id);
let inv=[]; try{ inv = $('Airtable · Get All Inventory').all().map(i=>i.json).filter(x=>x && x.id); }catch(e){}
let branches=[]; try{ branches = $('Airtable · Get All Branches').all().map(i=>F(i.json)).filter(b=>b.sucursal_id); }catch(e){}
const cityById={}; for(const b of branches){ cityById[String(b.sucursal_id)] = b.ciudad || ''; }

// Firma de cada fila de inventario (familia + cc + variante desde el nombre).
const invSig = inv.map(row=>{
  const f=F(row);
  const c=Number(f.cantidad); const u=(!isNaN(c)&&c>0)?c:1;
  return { fam:familyOf(f.familia_modelo||f.nombre_modelo), cc:extractCC(f.nombre_modelo),
           va:extractVariant(f.nombre_modelo), sid:String(f.sucursal_id||''), u };
});

const lista = models.map(m=>{
  const f=F(m); const nm=f.nombre||'';
  const mFam=familyOf(nm), mCC=extractCC(nm), mVar=extractVariant(nm);
  let disp=0; const cities={};
  for(const s of invSig){
    if(mFam && s.fam!==mFam) continue;
    if(mCC && s.cc!==mCC) continue;
    if(mVar && s.va!==mVar) continue;
    disp += s.u;
    const city = cityById[s.sid] || s.sid || '?';
    cities[city] = (cities[city]||0) + s.u;
  }
  const situacion = disp===0 ? 'agotado' : (disp<=3 ? 'pocas' : 'disponible');
  const precio = (f.precio===''?null:(f.precio??null));
  return {
    modelo: nm,
    categoria: f.categoria ?? null,
    cilindrada_cc: (f.cilindrada_cc ?? mCC),
    precio,
    precio_formato: (precio!=null ? '$'+Number(precio).toLocaleString('en-US') : null),
    disponibles: disp,
    situacion,
    ciudades: Object.keys(cities).sort((a,b)=>cities[b]-cities[a])
  };
}).sort((a,b)=> b.disponibles - a.disponibles);

const disp = lista.filter(x=>x.disponibles>0);
const agot = lista.filter(x=>x.disponibles===0);

return [{ json: {
  ok:true,
  total_modelos: lista.length,
  modelos: lista,
  disponibles_nombres: disp.map(x=>x.modelo),
  agotados_nombres: agot.map(x=>x.modelo),
  hay_disponibles: disp.length>0,
  _diag: { modelos_leidos: models.length, inventario_leido: inv.length, sucursales_leidas: branches.length },
  _from_cache:false
}}];
